#include "stock_native_client_drive_presentation.hpp"
namespace d=stock_native_client_drive;
extern "C" int player_camera_fixture(double window,const double*input,unsigned count,double*out){try{d::CameraHistory history(window);d::Point velocity{};for(unsigned i=0;i<count;++i){const auto*row=input+i*5;if(row[4]){history.reset(row[4]>1.?std::optional<d::Point>{d::Point{row[1],row[2],row[3]}}:std::nullopt);velocity={};}const auto result=history.sample({row[1],row[2],row[3]},row[0],velocity);velocity=result.velocity;for(unsigned j=0;j<3;++j){out[i*6+j]=result.velocity[j];out[i*6+j+3]=result.acceleration[j];}}return 1;}catch(...){return 0;}}
extern "C" int player_visual_laws(const double*input,double*out){try{d::PlayerDescriptor descriptor;descriptor.rotation_around_center=input[0];descriptor.motion.track_center=input[1];descriptor.motion.drive.forward=input[2];d::PlayerState state;state.speed=input[3];state.turn_speed=input[4];state.airborne=input[5];state.drive_throttle=input[6];const auto tracks=d::trackScroll(descriptor,state,-15.,30.);out[0]=tracks[0];out[1]=tracks[1];const auto mode=d::engineMode(input[7],input[8],input[9],state.speed);out[2]=mode.power;out[3]=mode.flags;const auto swing=d::accelerationSwing(mode.flags,int(input[10]),2.,1.);out[4]=bool(swing);out[5]=swing?swing->period:0.;out[6]=swing?swing->direction:0.;d::HydraulicPitch p;p.available=input[11];p.enabled=input[12];p.minimum=input[13];p.maximum=input[14];p.speed=input[15];p.center_z=input[16];p.gun_minimum=input[17];p.gun_maximum=input[18];const auto hydraulic=d::hydraulicCorrection(p,input[19],input[20],input[21],input[22]?std::optional<double>{input[23]}:std::nullopt,input[24],input[25]);out[7]=hydraulic.correction;for(unsigned j=0;j<3;++j)out[j+8]=hydraulic.translation[j];return 1;}catch(...){return 0;}}
